  (* [comment removed for export] *)
  Lemma kd_P : forall regs m (kel : word),
    getr regs 9 = kel ->
    exists regs',
      msteps SEGS (mkst regs (0x2c880 : word) m rom) (mkst regs' (0x2f80c : word) m rom)
      /\ getr regs' 2 = getr regs 2 /\ getr regs' 1 = Z_to_bv 64 0x2c888 /\ getr regs' 10 = kel
      /\ getr regs' 8 = getr regs 8 /\ getr regs' 9 = getr regs 9
      /\ regs_agree (fun r => In r [1; 10]%list) regs regs'.
